import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { MANIFEST_FILE } from '../../constants.js';
import manifestPlugin from '../../plugins/manifestPlugin.js';
function isExtensionFileMock(filepath, extensionPath) {
    const resolvedFilePath = path.resolve(process.cwd(), filepath);
    const resolvedExtensionPath = path.resolve(process.cwd(), extensionPath);
    const relativePath = path.relative(resolvedExtensionPath, resolvedFilePath);
    return !relativePath.startsWith('..') && !path.isAbsolute(relativePath);
}
vi.mock('../../utils', async () => {
    const originalModule = (await vi.importActual('../../utils'));
    return {
        ...originalModule,
        isExtensionFile: isExtensionFileMock,
    };
});
vi.mock('fs', () => {
    const readFileSyncMock = vi.fn((filename) => JSON.stringify({
        filename,
    }));
    return {
        default: {
            readFileSync: readFileSyncMock,
        },
        readFileSync: readFileSyncMock,
    };
});
const bundleEntry = {
    facadeModuleId: 'facadeModuleId',
    moduleIds: ['foo', 'bar', 'baz', 'node_modules/lodash'],
    modules: {
        foo: {
            renderedExports: ['bar'],
        },
        bar: {
            renderedExports: ['baz'],
        },
        baz: {
            renderedExports: [],
        },
        'node_modules/lodash': {
            renderedExports: ['get'],
        },
    },
};
